CREATE OR REPLACE FUNCTION public.get_team_conversation_previews() RETURNS TABLE (conversation_id uuid, last_message_id uuid, last_message_content text, last_message_type text, last_message_sender_id uuid, last_message_created_at timestamptz) LANGUAGE sql SECURITY DEFINER SET search_path = public STABLE AS $$ SELECT tc.id AS conversation_id, lm.id AS last_message_id, lm.content AS last_message_content, lm.message_type AS last_message_type, lm.sender_id AS last_message_sender_id, lm.created_at AS last_message_created_at FROM public.team_conversations tc JOIN public.team_conversation_members mem ON mem.conversation_id = tc.id AND mem.profile_id = (SELECT id FROM public.profiles WHERE user_id = auth.uid()) LEFT JOIN LATERAL (SELECT id, content, message_type, sender_id, created_at FROM public.team_messages WHERE conversation_id = tc.id ORDER BY created_at DESC LIMIT 1) lm ON true $$;
